# LeadGrove Modular Application Auto-Installer Script
import os, base64, sys

FILES = {'main.py': '', 'config.py': '', 'database/connection.py': '', 'database/init_db.py': '', 'models/schemas.py': '', 'services/auth_service.py': '', 'services/claude_auditor.py': '', 'services/identity_matcher.py': '', 'routers/auth.py': '', 'routers/dashboard.py': '', 'routers/health.py': '', 'routers/reports.py': '', 'routers/settings.py': '', 'routers/webhooks.py': ''}

def install():
    print("🚀 Unpacking LeadGrove Modular Application Files...")
    for rel_path, b64_content in FILES.items():
        dir_name = os.path.dirname(rel_path)
        if dir_name:
            os.makedirs(dir_name, exist_ok=True)
        raw_bytes = base64.b64decode(b64_content.encode('utf-8'))
        with open(rel_path, 'wb') as f:
            f.write(raw_bytes)
        print(f"  ✅ {rel_path} ({len(raw_bytes)} bytes)")
    print("\n🎉 LeadGrove Modular Application Setup Complete!")

if __name__ == '__main__':
    install()
